WHERE credit_memos.status >= 0 AND credit_memos.location_id IN (SELECT location_id FROM user_locations WHERE user_id = #{userId} GROUP BY location_id)

    AND credit_memos.created_by = #{userId}


    AND credit_memos.company_id = #{filter.companyId}


    AND credit_memos.status = #{filter.status}


    AND credit_memos.order_date >= #{filter.dateFrom}


    AND credit_memos.order_date <= #{filter.dateTo}


    AND (
        credit_memos.cm_code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR credit_memos.invoice_code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name_kh LIKE CONCAT('%', #{filter.searchText}, '%')
    )




            AND credit_memos.balance > 0


            AND credit_memos.balance <= 0

