UPDATE sales_orders SET


        balance = balance - #{balance},


        balance = balance + #{balance},


modified = NOW(),
modified_by = #{userId}
WHERE id = #{salesInvoiceId};

UPDATE credit_memos SET
balance = #{creditMemo.balance},
total_amount_invoice = #{creditMemo.totalAmount},
modified = NOW(),
modified_by = #{creditMemo.modifiedBy}
WHERE id = #{creditMemo.id}

UPDATE credit_memos SET


        balance = balance - #{balance}


        balance = #{balance}


        balance = balance + #{balance}


WHERE id = #{creditMemoId}

